import java.util.LinkedHashSet;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        Set<String> kota = new LinkedHashSet<String>();
        kota.add("Bandung");
        kota.add("Solo");
        kota.add("Bandung");
        kota.add("Medan");

        System.out.println(kota);
        System.out.println(kota.size());
        System.out.println(kota.contains("Solo"));

        kota.remove("Solo");
        for (String k : kota) {
            System.out.println("- " + k);
        }
    }
}

