import java.util.LinkedHashSet;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        String[] kata = {"java", "php", "java", "go", "php"};
        Set<String> unik = new LinkedHashSet<String>();
        for (String k : kata) {
            unik.add(k);
        }
        System.out.println(unik.size());
        System.out.println(unik);
    }
}

